/// Upon success, empty is returned. Upon failure, an error is returned instead.
///
/// # Errors
///
/// - [`ErrorCode::InvalidArgument`]: Failed to read the PTE.
/// - [`ErrorCode::BadAddress`]: The frame number is out of range.
///
#[verus_verify(external_body)]
